        var repo = new FakeBoardRepository(boardForMember: board);
        var sut = CreateSut(boardRepo: repo, boardMemberRepo: memberRepo);

        await sut.DeleteAsync(boardId);

        repo.DeletedBoardId.Should().Be(boardId);
    }

